={{ (() => {
  const webhookData = $node["Stripe Webhook"].json;
  const lookup = Array.isArray($json) ? $json : [];
  const evt = webhookData.body || webhookData;
  const t = (evt.type || '').toLowerCase();
  const obj = evt.data?.object || {};
  const isPaid    = t === 'checkout.session.completed' || t === 'invoice.payment_succeeded' || t === 'customer.subscription.created' || t === 'customer.subscription.updated';
  const isChurned = t === 'customer.subscription.deleted';
  const kind      = isChurned ? 'churned' : isPaid ? 'paid' : 'paid';
  const product   = 'mm_ctrl';
  const customerId = obj.customer || obj.id || null;
  const email      = obj.customer_email || obj.customer_details?.email || obj.receipt_email || null;
  const name       = obj.customer_details?.name || obj.metadata?.full_name || null;
  const plan       = obj.plan?.nickname || obj.items?.data?.[0]?.price?.nickname || obj.metadata?.plan || null;
  const mrr        = obj.plan?.amount ? obj.plan.amount / 100 : (obj.amount_total ? obj.amount_total / 100 : null);
  const utm        = obj.metadata?.utm_source || obj.metadata?.attribution_channel || null;
  const now        = new Date().toISOString();
  const lead       = lookup.length > 0 ? lookup[0] : null;
  const attribution_lead_id    = lead ? lead.id : null;
  const attribution_task_id    = lead ? (lead.promoted_task_id || null) : null;
  const attribution_channel    = lead ? (utm || ('agent:' + (lead.assignee_agent || 'unknown'))) : (utm || null);
  const attribution_confidence = lead ? 'exact_email' : (utm ? 'utm' : 'unattributed');
  return JSON.stringify({
    product, kind, email, full_name: name,
    stripe_customer_id: customerId,
    stripe_subscription_id: obj.subscription || obj.id || null,
    plan, mrr_usd: mrr,
    became_paid_at: isPaid && !isChurned ? now : null,
    churned_at:     isChurned ? now : null,
    source: utm,
    raw: evt,
    attribution_lead_id, attribution_task_id, attribution_channel, attribution_confidence,
  });
})() }}
